<?php
session_start();
require_once __DIR__.'/../lead-engine/config.php';
require_once __DIR__.'/../lead-engine/goliath-db.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-mobile-command.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rows($s,$p=[]){try{return gdb_all($s,$p)?:[];}catch(Throwable $e){return [];}}
function one($s,$p=[]){try{return gdb_one($s,$p)?:[];}catch(Throwable $e){return [];}}

$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
$brief=one("SELECT * FROM daily_briefs ORDER BY brief_date DESC,id DESC LIMIT 1");
$metrics=$brief && !empty($brief['metrics_json'])?json_decode($brief['metrics_json'],true):[];
$actions=$brief && !empty($brief['action_items_json'])?json_decode($brief['action_items_json'],true):[];
$timeline=rows("SELECT * FROM relationship_timeline ORDER BY is_new DESC, created_at DESC LIMIT 60");
$drafts=rows("SELECT ed.*, q.owner_name q_name,q.property_address q_address,q.town q_town,q.campaign FROM jessica_email_drafts ed LEFT JOIN jessica_relationship_queue q ON q.id=ed.queue_id WHERE ed.status IN ('pending_approval','approved') ORDER BY ed.created_at DESC LIMIT 12");
$contacts=rows("SELECT id,owner_name,property_address,town,completion_score,best_phone,phone_1,phone,best_email,email_1,recommended_blog,updated_at FROM scout_intel_dossiers WHERE handoff_status='ready_for_mark' ORDER BY COALESCE(completion_score,0) DESC,updated_at DESC LIMIT 12");
$appts=rows("SELECT * FROM appointment_requests WHERE status IN ('draft','pending','confirmed') ORDER BY COALESCE(start_time,created_at) ASC LIMIT 8");
