<section class="panel"><h2>Morning Brief</h2><div class="brief"><?=h($brief['summary']??'Run Refresh Brief to generate today’s command briefing.')?></div><?php foreach((array)$actions as $a): ?><div class="card"><b>Next Action</b><div class="muted"><?=h($a)?></div></div><?php endforeach; ?></section>
<section class="panel"><h2>Call Ready</h2><?php foreach($contacts as $c): $phone=$c['best_phone']?:$c['phone_1']?:$c['phone']?:''; $email=$c['best_email']?:$c['email_1']?:''; ?><a class="card" href="/dashboard/scout-ready-contacts.php#contact-<?=h($c['id'])?>"><b><?=h($c['owner_name'])?></b><div class="muted"><?=h($c['property_address'])?> · <?=h($c['town'])?></div><?php if($phone): ?><div class="phone"><?=h($phone)?></div><?php endif; ?><?php if($email): ?><div class="email"><?=h($email)?></div><?php endif; ?><span class="pill"><?=h($c['completion_score'])?>%</span></a><?php endforeach; ?></section>
<section class="panel"><h2>Jessica Drafts</h2><?php foreach($drafts as $d): ?><a class="card" href="/dashboard/jessica-relationship-center.php#draft-<?=h($d['id'])?>"><b><?=h($d['to_name']?:$d['q_name'])?></b><div class="muted"><?=h($d['subject'])?></div><span class="pill new"><?=h($d['status'])?></span><span class="pill"><?=h($d['campaign'])?></span></a><?php endforeach; ?></section>
<section class="panel"><h2>Appointments</h2><?php foreach($appts as $a): ?><div class="card"><b><?=h($a['title'])?></b><div class="muted"><?=h($a['client_name'])?> · <?=h($a['start_time'])?></div><div><?=h($a['location'])?></div><span class="pill"><?=h($a['status'])?></span></div><?php endforeach; ?></section>
<section class="panel"><h2>Live Timeline</h2><?php foreach($timeline as $t): ?><div class="card"><b><?=!empty($t['is_new'])?'🔴 ':''?><?=h($t['title'])?></b><div class="muted"><?=h($t['executive_key'])?> · <?=h($t['event_type'])?> · <?=h($t['created_at'])?></div><div><?=h($t['details'])?></div></div><?php endforeach; ?></section>
